import{_ as n,C as e,o as d,c as s,j as a,a as h,E as r,a2 as o}from"./chunks/framework.B-bxTAy7.js";const S=JSON.parse('{"title":"嵌入式开发 · 课程主页","description":"以 STM32 / ARM Cortex-M 为载体的嵌入式课程：开发环境、寄存器思维、时钟树、GPIO、中断、定时器 PWM、UART、SPI/I²C、ADC/DMA、FreeRTOS 与综合项目。","frontmatter":{"title":"嵌入式开发 · 课程主页","description":"以 STM32 / ARM Cortex-M 为载体的嵌入式课程：开发环境、寄存器思维、时钟树、GPIO、中断、定时器 PWM、UART、SPI/I²C、ADC/DMA、FreeRTOS 与综合项目。"},"headers":[],"relativePath":"embedded/index.md","filePath":"embedded/index.md","lastUpdated":1792416913000}'),g={name:"embedded/index.md"};function p(_,t,u,P,T,A){const l=e("Meta"),i=e("CourseRoadmap");return d(),s("div",null,[t[0]||(t[0]=a("h1",{id:"嵌入式开发",tabindex:"-1"},[h("嵌入式开发 "),a("a",{class:"header-anchor",href:"#嵌入式开发","aria-label":'Permalink to "嵌入式开发"'},"​")],-1)),r(l,{time:"8 min",level:"指南",note:"从「会算电路」到「让芯片干活」：MCU 架构、外设、RTOS 一条线打通"}),t[1]||(t[1]=o('<p>前面三门课让你<strong>看懂</strong>电路与信号：电工学讲连续量，数电讲逻辑状态，模电讲模拟器件的微观机理。但它们停在了原理——你还没真的让一个芯片去<strong>读一个按键、发一串串口、控一台电机</strong>。</p><p>嵌入式开发就是这最后一步：<strong>把物理世界和数字世界连起来，让 MCU 按你的程序跑起来</strong>。本课程以 <strong>STM32（ARM Cortex-M 内核）</strong> 为载体——工业与教学里最主流的 32 位单片机，资料多、生态全；但讲的概念（时钟树、GPIO、中断、定时器、UART/SPI/I²C、ADC/DMA、RTOS）是<strong>所有 MCU 通用的</strong>，换到 ESP32、GD32、NXP 也只差寄存器名字。</p><h2 id="学完能得到什么" tabindex="-1">学完能得到什么 <a class="header-anchor" href="#学完能得到什么" aria-label="Permalink to &quot;学完能得到什么&quot;">​</a></h2><ul><li>从零建一个 STM32 工程，独立完成编译、下载、断点调试与串口打印；</li><li>读懂时钟树，算清 PLL 与 AHB/APB 分频，知道「外设为什么不工作」的第一嫌疑是没开时钟；</li><li>把 GPIO 四种模式、上下拉、开漏/推挽与实际接法对应起来，写出不抖的按键检测；</li><li>配置中断与 NVIC 优先级，解释抢占、子优先级、咬尾与晚到；</li><li>用定时器做 PWM、输入捕获与编码器测速，用 UART/SPI/I²C 与传感器通信；</li><li>用 ADC + DMA 采数据、做滤波；用 FreeRTOS 把裸机 super-loop 拆成任务；</li><li>做一次完整的低功耗设计，知道 Sleep/Stop/Standby 的代价与唤醒源。</li></ul><h2 id="章节路线" tabindex="-1">章节路线 <a class="header-anchor" href="#章节路线" aria-label="Permalink to &quot;章节路线&quot;">​</a></h2>',5)),r(i,{course:"embedded"}),t[2]||(t[2]=o('<h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>顺序</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>速通</strong>（约 5 h）</td><td>01 → 02 → 04 → 05 → 06 → 07 → 08</td><td>只求能点灯、能串口、能中断</td></tr><tr><td><strong>系统</strong>（约 9 h）</td><td>01 → 12 顺序读，每个外设都上手接一次</td><td>要独立做项目</td></tr><tr><td><strong>补强</strong></td><td>时钟算错回 04，中断乱了回 06，通信不通回 08/09</td><td>已经在写但常踩坑</td></tr></tbody></table><h2 id="和前三门课的关系-以及两种读法" tabindex="-1">和前三门课的关系（以及两种读法） <a class="header-anchor" href="#和前三门课的关系-以及两种读法" aria-label="Permalink to &quot;和前三门课的关系（以及两种读法）&quot;">​</a></h2><ul><li><strong>电工学</strong>：推挽/开漏输出、上下拉电阻、电平标准（TTL/CMOS）——在 GPIO 章直接复用，不用重学。</li><li><strong>数字电路</strong>：寄存器、时序、总线仲裁（三态/开漏总线）——UART/SPI/I²C 的帧和波形，本质是数电时序的工业版。</li><li><strong>模拟电子</strong>：ADC 把模拟电压量化成数字码、运放做信号调理、PWM 滤波出模拟量——模电的「模拟↔数字接口」在这里闭环。</li></ul><p>两种读法：</p><ul><li><strong>有电路基础</strong>：跳过「为什么推挽」「为什么上拉」这类铺垫，直奔「寄存器怎么配、HAL 怎么用、坑在哪」。</li><li><strong>零基础直接来</strong>：每章都从「这个器件/概念在物理上是什么」讲起，依赖的电路知识用前置知识胶囊兜底。</li></ul><h2 id="暂不涉及的内容" tabindex="-1">暂不涉及的内容 <a class="header-anchor" href="#暂不涉及的内容" aria-label="Permalink to &quot;暂不涉及的内容&quot;">​</a></h2><p>以下不是不学，而是明确<strong>不在这一版课程里</strong>：CAN/LIN 总线、USB、以太网、嵌入式 Linux（Cortex-A）、LVGL 图形界面、OTA/固件安全、MISRA-C 规范。先把手脚（MCU 外设 + RTOS）练熟，再选赛道深挖。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>想补通信时序基础：<a href="./../digital/flip-flops">数字电路 · 触发器</a></li><li>想做信号调理：<a href="./../analog/signal-processing">模拟电子 · 信号的运算和处理</a></li><li>想知道哪些章节能当教材读：<a href="./../guide/status">内容状态与成熟度</a></li></ul>',10))])}const c=n(g,[["render",p]]);export{S as __pageData,c as default};
